export function getDishDescription(dishName: string): string | undefined {
  if (!dishName) return undefined;
  
  // 1. Direct match
  if (dishDescriptions[dishName]) {
    return dishDescriptions[dishName];
  }
  
  // 2. Clean extra price notes
  const clean = dishName.replace(/\(Extra Rs\.\d+\/-\)/gi, "").trim();
  if (dishDescriptions[clean]) {
    return dishDescriptions[clean];
  }
  
  // 3. Case-insensitive normalized lookup
  const normalize = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, "");
  const target = normalize(dishName);
  
  for (const [key, value] of Object.entries(dishDescriptions)) {
    if (normalize(key) === target) {
      return value;
    }
  }
  
  return undefined;
}
